#!/usr/bin/env node
// Restores the notification bits `cap sync` cannot preserve.
//
// Why this exists: `android/` is gitignored and fully regenerated by
// `npx cap add android` (docs/CAPACITOR.md), so anything added to the manifest
// by hand is lost on the next regenerate — taking notification rendering down
// with it. Same shape as patch-android-firebase.mjs, and it must be re-run after
// every sync for the same reason.
//
// What the plugins already merge in, and this therefore does NOT duplicate:
// POST_NOTIFICATIONS, WAKE_LOCK and RECEIVE_BOOT_COMPLETED arrive from
// @capacitor/local-notifications' own manifest, and the FCM MessagingService
// from @capacitor/push-notifications'. Only these two are genuinely missing:
//
//   SCHEDULE_EXACT_ALARM  syncReminders.ts schedules with allowWhileIdle, which
//                         maps to setExactAndAllowWhileIdle. On Android 12+ that
//                         throws SecurityException without this permission, so
//                         the LOCAL reminder path dies at the moment it fires —
//                         long after anything that could report it. Push takes
//                         over when it registers (see setServerDelivery), which
//                         makes this the fallback path, not the usual one.
//
//   default_notification_icon
//                         Without it Android falls back to the launcher icon and,
//                         from Android 5 on, redraws it from its alpha alone — a
//                         full-colour icon becomes a white square. The push was
//                         always arriving; it just had no drawable it could use.
//
// NOT set here: com.google.firebase.messaging.default_notification_channel_id.
// The meta-data does not CREATE a channel — it names one the app is expected to
// have created already, and on Android 8+ naming a channel that does not exist
// is worse than naming none, because the notification can be dropped outright.
// Nothing in lib/notifications/ calls LocalNotifications.createChannel() yet, so
// adding the line would trade a cosmetic bug for a silent delivery one. FCM's
// own "Miscellaneous" fallback channel is used until that channel is created.

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')

const ICON_NAME = 'ic_stat_kitto.xml'
const ICON_SOURCE = join(REPO_ROOT, 'native/android/res/drawable', ICON_NAME)
const ICON_DEST_DIR = join(REPO_ROOT, 'android/app/src/main/res/drawable')

const MANIFEST = join(REPO_ROOT, 'android/app/src/main/AndroidManifest.xml')

const PERMISSION = 'android.permission.SCHEDULE_EXACT_ALARM'
const PERMISSION_LINE = `    <uses-permission android:name="${PERMISSION}" />`

const ICON_META_NAME = 'com.google.firebase.messaging.default_notification_icon'
const ICON_META_BLOCK =
  '        <meta-data\n' +
  `            android:name="${ICON_META_NAME}"\n` +
  '            android:resource="@drawable/ic_stat_kitto" />'

function main() {
  if (!existsSync(MANIFEST)) {
    // Not fatal, by design — matches patch-android-firebase.mjs, so a teammate
    // who has not generated the native project yet gets told rather than stopped.
    console.warn('! No android/ project yet — run `npx cap add android` first.')
    return
  }

  copyIcon()
  patchManifest()
}

function copyIcon() {
  if (!existsSync(ICON_SOURCE)) {
    console.warn(`! No ${ICON_NAME} at native/android/res/drawable — status-bar icon will be a white square.`)
    return
  }

  mkdirSync(ICON_DEST_DIR, { recursive: true })
  copyFileSync(ICON_SOURCE, join(ICON_DEST_DIR, ICON_NAME))
  console.log(`✓ ${ICON_NAME} → android/app/src/main/res/drawable/`)
}

/** Idempotent: this runs after every sync, and a sync does not always regenerate. */
function patchManifest() {
  let xml = readFileSync(MANIFEST, 'utf8')
  const changes = []

  if (xml.includes(PERMISSION)) {
    console.log('· SCHEDULE_EXACT_ALARM already present')
  } else {
    // Before the closing tag rather than after <manifest>, so it sits with the
    // INTERNET permission Capacitor writes at the bottom.
    xml = xml.replace('</manifest>', `${PERMISSION_LINE}\n</manifest>`)
    changes.push('SCHEDULE_EXACT_ALARM')
  }

  if (xml.includes(ICON_META_NAME)) {
    console.log('· default_notification_icon already present')
  } else if (!existsSync(ICON_SOURCE)) {
    console.warn('! Skipping default_notification_icon — the drawable is missing, and pointing at an absent resource fails the build.')
  } else {
    // Last </application> close: the meta-data has to live inside it.
    const at = xml.lastIndexOf('    </application>')
    if (at === -1) {
      console.warn('! Could not find </application> — manifest is not the shape this expects; left unchanged.')
    } else {
      xml = `${xml.slice(0, at)}${ICON_META_BLOCK}\n${xml.slice(at)}`
      changes.push('default_notification_icon')
    }
  }

  if (changes.length === 0) {
    console.log('✓ AndroidManifest.xml already patched — nothing to do')
    return
  }

  writeFileSync(MANIFEST, xml)
  console.log(`✓ AndroidManifest.xml patched (${changes.join(', ')})`)
}

main()
